mapper.select:
SELECT COALESCE(SUM(CASE WHEN type = #{incomeCode} THEN amount ELSE 0 END), 0) AS income,
       COALESCE(SUM(CASE WHEN type = #{expenseCode} THEN amount ELSE 0 END), 0) AS expense
FROM team_ledger_entry
WHERE team_id = #{teamId} AND is_deleted = 0

    AND occurred_at >= #{from}


    AND occurred_at <= #{to}


    AND type = #{type}


    AND category_id = #{categoryId}


    AND player_id = #{playerId}


    AND activity_id = #{activityId}

SELECT DATE(occurred_at) AS entry_date,

FROM team_ledger_entry
WHERE team_id = #{teamId} AND is_deleted = 0

    AND occurred_at >= #{from}


    AND occurred_at <= #{to}


    AND type = #{type}


    AND category_id = #{categoryId}


    AND player_id = #{playerId}


    AND activity_id = #{activityId}


    AND description LIKE CONCAT('%', #{keyword}, '%')

GROUP BY DATE(occurred_at)
ORDER BY entry_date DESC
